import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const o="/assets/RegLayout.CyLLslIC.png",c=JSON.parse('{"title":"RegLayout","description":"","frontmatter":{},"headers":[{"level":1,"title":"RegLayout","slug":"reglayout"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/数据类型/RegLayout.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/数据类型/RegLayout.md"}'),l={name:"api/SIMD-API/基础API/Reg矢量计算/数据类型/RegLayout.md"};function p(i,a,g,u,R,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="reglayout" tabindex="-1">RegLayout <a class="header-anchor" href="#reglayout" aria-label="Permalink to &quot;RegLayout&quot;">​</a></h1><p>源操作数与目的操作数类型位宽不同时，可以分为两种情况：</p><ol><li>源操作数与目的操作数位宽比为1:2或2:1。</li><li>源操作数与目的操作数位宽比为1:4或4:1。</li></ol><p>该数据结构是为了在两种情况中决定读或写的位置，在情景1下，可以将一个256B大小的<a href="./../寄存器数据类型/RegTensor.html">RegTensor</a>分为两部分，对于每一字节，其索引为下标i%2；在情景2下，可以将一个256B大小的RegTensor分为四部分，对于每一字节，其索引为下标i%4。RegLayout的取值如下：</p><ul><li>RegLayout::ZERO，写入索引0的位置</li><li>RegLayout::ONE，写入索引1的位置</li><li>RegLayout::TWO，写入索引2的位置</li><li>RegLayout::THREE，写入索引3的位置</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum class RegLayout {</span></span>
<span class="line"><span>    UNKNOWN = -1,</span></span>
<span class="line"><span>    ZERO,</span></span>
<span class="line"><span>    ONE,</span></span>
<span class="line"><span>    TWO,</span></span>
<span class="line"><span>    THREE</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><img src="`+o+'" alt=""></p><p>如图所示，RegLayout::ZERO/RegLayout::ONE这2种模式仅在位宽比值1:2或2:1的情况下可以使用，例如float32转int16, 位宽比为2比1。例如，对于位宽为2:1的数据类型转换，可以通过RegLayout选定写入数据的位置。当选择RegLayout::ZERO时，数据写入索引为0的位置，当选择RegLayout::ONE时，数据写入索引为1的位置。</p><p>RegLayout::ZERO/RegLayout::ONE/RegLayout::TWO/RegLayout::THREE这4种模式仅在位宽比值1比4或4比1的情况下可以使用，例如float32转int8,位宽比为4比1。例如，对于位宽为4:1的数据类型转换，当选择RegLayout::ZERO时，数据写入索引为0的位置；当选择RegLayout::ONE时，数据写入索引为1的位置；当选择RegLayout::TWO时，数据写入索引为2的位置；当选择RegLayout::THREE时，数据写入索引为3的位置。</p>',9)])])}const L=e(l,[["render",p]]);export{c as __pageData,L as default};
